B.a64=new A.N(B.cq,[u.Q,"Robotics Club","\u062a\u0637\u0648\u064a\u0631 \u0648\u0635\u064a\u0627\u0646\u0629 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u062c\u0648\u0627\u0644 \u0645\u062a\u0643\u0627\u0645\u0644\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flutter \u0648 Django\u060c \u0648\u0628\u0646\u0627\u0621 APIs \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0648\u0633\u0639 \u0648\u0648\u0627\u062c\u0647\u0627\u062a \u0645\u0633\u062a\u062e\u062f\u0645 \u0645\u062a\u062c\u0627\u0648\u0628\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0646\u0635\u0627\u062a. \u062a\u0635\u0645\u064a\u0645 \u0648\u062f\u0645\u062c \u0642\u0648\u0627\u0639\u062f \u0628\u064a\u0627\u0646\u0627\u062a PostgreSQL \u0648 SQLite\u060c \u0648\u062a\u0637\u0628\u064a\u0642 \u0625\u062f\u0627\u0631\u0629 \u0628\u064a\u0627\u0646\u0627\u062a \u0622\u0645\u0646\u0629 \u0648\u062e\u062f\u0645\u0627\u062a \u062e\u0627\u0641\u064a\u0629 \u0641\u0639\u0627\u0644\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Python. \u062a\u063a\u0644\u064a\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Docker \u0648\u062f\u0639\u0645 \u0627\u0644\u0646\u0634\u0631 \u0627\u0644\u0633\u062d\u0627\u0628\u064a \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 AWS. \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0627\u0644\u0641\u0631\u064a\u0642 \u0644\u062a\u0642\u062f\u064a\u0645 \u062d\u0644\u0648\u0644 \u0645\u0648\u062b\u0648\u0642\u0629 \u0648\u062c\u0627\u0647\u0632\u0629 \u0644\u0644\u0625\u0646\u062a\u0627\u062c \u0628\u062f\u0621\u064b\u0627 \u0645\u0646 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0627\u0644\u062e\u0627\u0641\u064a\u0629 \u0648\u062d\u062a\u0649 \u062a\u0637\u0648\u064a\u0631 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u062c\u0648\u0627\u0644.",2024,1,2024,6,B.aY,B.o],t.M)
B.a66=new A.N(B.cq,["\u0645\u0637\u0648\u0631 \u0623\u0630\u0631\u0639 \u0631\u0648\u0628\u0648\u062a\u064a\u0629 \u0645\u0632\u062f\u0648\u062c\u0629 (Dual Arms Developer)","Robotics Club","\u062a\u0637\u0648\u064a\u0631 \u0648\u062f\u0645\u062c \u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0644\u0646\u0638\u0627\u0645 \u0631\u0648\u0628\u0648\u062a\u064a \u062b\u0646\u0627\u0626\u064a \u0627\u0644\u0623\u0630\u0631\u0639\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0639\u0628\u0631 \u0627\u0644\u062a\u062d\u0643\u0645 \u0628\u0627\u0644\u062d\u0631\u0651\u0643\u0629\u060c \u0648\u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0633\u064a\u0637\u0629 \u0644\u0644\u0631\u0648\u0628\u0648\u062a\u0627\u062a (Robotics Middleware)\u060c \u0648\u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u062d\u0627\u0633\u0648\u0628\u064a\u0629\u060c \u0648\u0648\u0627\u062c\u0647\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645. \u0628\u0646\u0627\u0621 \u0645\u0643\u0648\u0646\u0627\u062a \u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 ROS \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 C++ \u0648 Python \u0648 OpenCV \u0644\u0644\u062a\u062d\u0643\u0645 \u0627\u0644\u0631\u0648\u0628\u0648\u062a\u064a\u060c \u0648\u0627\u0644\u0625\u062f\u0631\u0627\u0643\u060c \u0648\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0646\u0638\u0627\u0645. \u062a\u0637\u0648\u064a\u0631 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u062f\u0627\u0639\u0645\u0629 \u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u0645\u0646\u0635\u0627\u062a \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flutter \u0648 Dart \u0648 Firebase \u0648 Qt\u060c \u0648\u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0627\u0644\u0641\u0631\u064a\u0642 \u0644\u062f\u0645\u062c \u0648\u0627\u062e\u062a\u0628\u0627\u0631 \u0648\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0645\u0646\u0635\u0629 \u0627\u0644\u0631\u0648\u0628\u0648\u062a\u064a\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.",2022,9,2023,10,B.uz,B.o],t.M)
B.a61=new A.N(B.cq,["\u0645\u0647\u0646\u062f\u0633 \u0623\u0646\u0638\u0645\u0629 (Systems Engineer)","Robotics Club","\u0627\u0644\u0639\u0645\u0644 \u0643\u0645\u0647\u0646\u062f\u0633 \u0623\u0646\u0638\u0645\u0629\u060c \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0648\u062f\u0645\u062c \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0631\u0648\u0628\u0648\u062a\u064a\u0629 \u0639\u0628\u0631 \u0637\u0628\u0642\u0627\u062a \u0627\u0644\u0639\u062a\u0627\u062f \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a. \u062a\u0635\u0645\u064a\u0645 \u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u0645\u0646\u0635\u0627\u062a \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flutter \u0648 Dart \u0648 Firebase \u0648 Qt\u060c \u0623\u062b\u0646\u0627\u0621 \u0628\u0646\u0627\u0621 \u0648\u062f\u0645\u062c \u0623\u0646\u0638\u0645\u0629 \u0631\u0648\u0628\u0648\u062a\u064a\u0629 \u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 ROS \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Python. \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639 \u0641\u0631\u0642 \u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u062a\u062e\u0635\u0635\u0627\u062a \u0644\u062d\u0644 \u0627\u0644\u062a\u062d\u062f\u064a\u0627\u062a \u0627\u0644\u062a\u0642\u0646\u064a\u0629\u060c \u0648\u062a\u062d\u0633\u064a\u0646 \u0645\u0648\u062b\u0648\u0642\u064a\u0629 \u0627\u0644\u0646\u0638\u0627\u0645\u060c \u0648\u062f\u0639\u0645 \u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0631\u0648\u0628\u0648\u062a\u0627\u062a \u0645\u0646 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0623\u0648\u0644 \u0648\u062d\u062a\u0649 \u0627\u0644\u062f\u0645\u062c \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631.",2021,5,2022,6,B.ww,B.o],t.M)
